import 'dart:async';
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

/// gh-1455: a background shell job must own its lifecycle. The run's cancel
/// token (Agent.abort, the run-idle watchdog, steering teardown) used to be
/// forwarded into the job's ShellExecOptions, so an aborted run tore down
/// every live job — and `bash_job stop` from inside the dying batch then
/// cancelled the whole run on top of the abort.
///
/// The contract pinned here: caller cancel tokens NEVER reach job space
/// (the registry firewalls them), and the foreground-as-job bash path
/// unwinds on a run cancel by handing the still-running job back to the
/// background — never by killing it.
void main() {
  late Directory tempDir;
  late LocalExecutionEnv env;
  late ShellJobRegistry registry;

  setUp(() {
    tempDir = Directory.systemTemp.createTempSync('gh1455-job-test-');
    env = LocalExecutionEnv(cwd: tempDir.path);
    registry = ShellJobRegistry(env: env);
  });

  tearDown(() async {
    for (final entry in registry.jobs) {
      if (entry.isRunning) await entry.stop();
    }
    if (tempDir.existsSync()) tempDir.deleteSync(recursive: true);
  });

  Future<ShellJobEntry> waitForJob() async {
    final deadline = DateTime.now().add(const Duration(seconds: 5));
    while (registry.jobs.isEmpty) {
      if (DateTime.now().isAfter(deadline)) fail('job never started');
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }
    return registry.jobs.single;
  }

  test(
    'cancelling the caller run token does not stop a registry job',
    () async {
      final runTokenSource = CancelTokenSource();
      final entry = await registry.start(
        'sleep 60',
        options: ShellExecOptions(cancelToken: runTokenSource.token),
      );
      expect(entry.isRunning, isTrue);
      runTokenSource.cancel('run aborted');
      // Give a forwarded token one event-loop turn to tear the job down.
      await Future<void>.delayed(const Duration(milliseconds: 300));
      expect(
        entry.isRunning,
        isTrue,
        reason: 'a job owns its lifecycle, not the run that started it',
      );
      await entry.stop();
      await entry.settled;
      expect(entry.isRunning, isFalse);
      expect(entry.exitCode, isNot(0));
      expect(entry.stopReason, 'stopped');
    },
  );

  test('a run-token cancel during foreground-as-job bash hands the running '
      'job back to the background instead of killing it', () async {
    final runTokenSource = CancelTokenSource();
    final yieldSource = CancelTokenSource();
    final tool = shellTool(env, jobs: registry);
    final resultFuture = runZoned(
      () => tool.execute({'command': 'sleep 60'}, runTokenSource.token, null),
      zoneValues: {yieldTokenZoneKey: yieldSource.token},
    );
    final entry = await waitForJob();
    expect(entry.isRunning, isTrue);

    // The "run" aborts mid-call.
    runTokenSource.cancel('run aborted');
    final result = await resultFuture;
    final text = (result.content.single as TextContent).text;
    expect(text, contains('background job ${entry.id}'));
    expect(text, contains('NOT killed'));

    expect(
      entry.isRunning,
      isTrue,
      reason: 'aborting the run must not kill a running job',
    );
    await entry.stop();
    await entry.settled;
    expect(entry.stopReason, 'stopped');
  });

  test('a supervisor cancel-retry (StuckCallFollowUp on the call token) fails '
      'the call with Command aborted but keeps the job running', () async {
    final runTokenSource = CancelTokenSource();
    final yieldSource = CancelTokenSource();
    final tool = shellTool(env, jobs: registry);
    final resultFuture = runZoned(
      () => tool.execute({'command': 'sleep 60'}, runTokenSource.token, null),
      zoneValues: {yieldTokenZoneKey: yieldSource.token},
    );
    final entry = await waitForJob();
    expect(entry.isRunning, isTrue);

    // The stuck-call supervisor's cancel_retry cancels the CALL token
    // with a StuckCallFollowUp reason: the attempt fails like the
    // pre-gh-1455 token-kill, but the job is NOT killed.
    runTokenSource.cancel(const StuckCallFollowUp('cancel_retry: stuck'));
    await expectLater(
      resultFuture,
      throwsA(
        isA<StateError>().having(
          (e) => e.message,
          'message',
          contains('Command aborted'),
        ),
      ),
    );
    expect(
      entry.isRunning,
      isTrue,
      reason: 'the supervisor retry must not kill the job either',
    );
    await entry.stop();
    await entry.settled;
    expect(entry.stopReason, 'stopped');
  });
}

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

const _model = Model(
  id: 'test-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: 100000,
  maxTokens: 4096,
);

AssistantMessage _assistant({
  List<ContentBlock> content = const [],
  StopReason stopReason = StopReason.stop,
}) {
  return AssistantMessage(
    content: content,
    api: 'test-api',
    provider: 'test-provider',
    model: 'test-model',
    usage: Usage.zero,
    stopReason: stopReason,
    timestamp: DateTime.utc(2026),
  );
}

List<AssistantMessageEvent> _textTurn(String text) {
  final empty = _assistant();
  final partial = _assistant(content: [TextContent(text: text)]);
  return [
    StartEvent(partial: empty),
    TextStartEvent(contentIndex: 0, partial: empty),
    TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
    DoneEvent(reason: StopReason.stop, message: partial),
  ];
}

List<AssistantMessageEvent> _toolTurn(List<ToolCall> calls) {
  final empty = _assistant();
  final partial = _assistant(content: calls, stopReason: StopReason.toolUse);
  final events = <AssistantMessageEvent>[StartEvent(partial: empty)];
  for (var i = 0; i < calls.length; i++) {
    events
      ..add(ToolCallStartEvent(contentIndex: i, partial: empty))
      ..add(
        ToolCallEndEvent(contentIndex: i, toolCall: calls[i], partial: partial),
      );
  }
  events.add(DoneEvent(reason: StopReason.toolUse, message: partial));
  return events;
}

class _FakeStreamFunction {
  _FakeStreamFunction(this.turns);

  final List<List<AssistantMessageEvent>> turns;
  final contexts = <Context>[];

  int get calls => contexts.length;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final stream = AssistantMessageEventStream();
    for (final event in turns.removeAt(0)) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

Tool _tool(String name) {
  return Tool(name: name, description: '$name tool', parameters: const {});
}

/// gh-1455: a CancelledException escaping a tool call is the run's
/// DELIBERATE shutdown (the shell tool's own first-line guard, the
/// stuck-call supervisor, a tool's throwIfCancelled) — not a tool failure
/// and not a harness defect. The generic `_errorToolResult` path used to
/// render it with the "uncaught exception inside the harness tool
/// implementation" hint, telling the model its bash tool is broken and to
/// route around it (the transcript symptom: `Tool error (bash):
/// CancelledException: run was aborted by signal …`).
void main() {
  test('a CancelledException from a tool renders as a deliberate cancel, '
      'not a harness defect', () async {
    final fake = _FakeStreamFunction([
      _toolTurn([ToolCall(id: 'c1', name: 'bash', arguments: const {})]),
      _textTurn('done'),
    ]);
    final agent = Agent(
      model: _model,
      streamFunction: fake.call,
      toolExecutor: (toolCall, cancelToken, onUpdate) async {
        throw CancelledException('run was aborted by signal');
      },
    );
    agent.state.tools = [_tool('bash')];

    await agent.prompt('start the long thing');

    final toolResult = agent.state.messages
        .whereType<ToolResultMessage>()
        .single;
    final text = (toolResult.content.single as TextContent).text;
    expect(text, contains('Tool error (bash):'));
    expect(text, contains('run was aborted'));
    expect(text, contains('tool not started'));
    expect(text, isNot(contains('uncaught exception inside the harness')));
    // The cancel reason survives so the model (and the transcript) can see
    // WHO cancelled the run — e.g. the run-idle watchdog.
    expect(text, contains('run was aborted by signal'));
  });
}

