/// gh-1455 review: shape a settled/supervisor-abort job log exactly like
/// the classic inline path — tail-truncate, then head-prefix the rewrite
/// notice (the notice rides AFTER truncation: _truncateTail keeps the
/// TAIL, so a head-prefixed notice is cut exactly when the output is long
/// enough to truncate).
String _shapeJobLogOutput(String rawOutput, {String? rewriteNotice}) {
  final truncation = _truncateTail(rawOutput);
  var output = !truncation.truncated
      ? rawOutput
      : '${truncation.content}\n[Showing lines '
            '${truncation.totalLines - truncation.outputLines + 1}-'
            '${truncation.totalLines} of ${truncation.totalLines}.]';
  if (rewriteNotice != null) output = '$rewriteNotice\n$output';
  return output;
}
