```dart
/// Shapes a job's log for an inline tool result exactly like the classic
/// foreground path: tail-truncate to the tool budget (issue #1408 AC3 —
/// the rewrite notice rides AFTER truncation, never before: _truncateTail
/// keeps the TAIL, so a head-prefixed notice is cut exactly when the
/// output is long enough to truncate, silently defeating the "the agent
/// sees the rewrite" contract).
String _shapeInlineJobLog(String rawOutput, {String? rewriteNotice}) {
  final truncation = _truncateTail(rawOutput);
  var output = !truncation.truncated
      ? rawOutput
      : '${truncation.content}\n[Showing lines '
            '${truncation.totalLines - truncation.outputLines + 1}-'
            '${truncation.totalLines} of ${truncation.totalLines}.]';
  if (rewriteNotice != null) output = '$rewriteNotice\n$output';
  return output;
}
```

