        env: shellEnv,
        sessionRoot: '/sessions',
        jobs: const JobsConfig(),
      ),
      io: io,
      streamFunction: FakeStreamFunction([textTurn('ok')]).call,
    );
    // A previous run left one entry behind: verifying it needs the OS
