    const dir = '/work';
    await shellEnv.createDir('$dir/.fah/bash_jobs');
    await shellEnv.writeFile(
      '$dir/.fah/bash_jobs/running.json',
      jsonEncode([
        {
          'id': 'sh-ghost',
          'command': 'sleep 99 & wait',
          'pid': '424242',
          'startedAtMs': DateTime.now().millisecondsSinceEpoch,
        },
      ]),
