import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

const _model = Model(
  id: 'test-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: 100000,
  maxTokens: 4096,
);

AssistantMessage _assistant({
  List<ContentBlock> content = const [],
  StopReason stopReason = StopReason.stop,
}) {
  return AssistantMessage(
    content: content,
    api: 'test-api',
    provider: 'test-provider',
    model: 'test-model',
    usage: Usage.zero,
    stopReason: stopReason,
    timestamp: DateTime.utc(2026),
  );
}

List<AssistantMessageEvent> _textTurn(String text) {
  final empty = _assistant();
  final partial = _assistant(content: [TextContent(text: text)]);
  return [
    StartEvent(partial: empty),
    TextStartEvent(contentIndex: 0, partial: empty),
    TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
    DoneEvent(reason: StopReason.stop, message: partial),
  ];
}

List<AssistantMessageEvent> _toolTurn(List<ToolCall> calls) {
  final empty = _assistant();
  final partial = _assistant(content: calls, stopReason: StopReason.toolUse);
  final events = <AssistantMessageEvent>[StartEvent(partial: empty)];
  for (var i = 0; i < calls.length; i++) {
    events
      ..add(ToolCallStartEvent(contentIndex: i, partial: empty))
      ..add(
        ToolCallEndEvent(contentIndex: i, toolCall: calls[i], partial: partial),
      );
  }
  events.add(DoneEvent(reason: StopReason.toolUse, message: partial));
  return events;
}

class _FakeStreamFunction {
  _FakeStreamFunction(this.turns);

  final List<List<AssistantMessageEvent>> turns;
  final contexts = <Context>[];

  int get calls => contexts.length;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final stream = AssistantMessageEventStream();
    for (final event in turns.removeAt(0)) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

Tool _tool(String name) {
  return Tool(name: name, description: '$name tool', parameters: const {});
}

/// gh-1455: a CancelledException escaping a tool call is the run's
/// DELIBERATE shutdown (the shell tool's own first-line guard, the
/// stuck-call supervisor, a tool's throwIfCancelled) — not a tool failure
/// and not a harness defect. The generic `_errorToolResult` path used to
/// render it with the "uncaught exception inside the harness tool
/// implementation" hint, telling the model its bash tool is broken and to
/// route around it (the transcript symptom: `Tool error (bash):
/// CancelledException: run was aborted by signal …`).
void main() {
  test('a CancelledException from a tool renders as a deliberate cancel, '
      'not a harness defect', () async {
    final fake = _FakeStreamFunction([
      _toolTurn([ToolCall(id: 'c1', name: 'bash', arguments: const {})]),
      _textTurn('done'),
    ]);
    final agent = Agent(
      model: _model,
      streamFunction: fake.call,
      toolExecutor: (toolCall, cancelToken, onUpdate) async {
        throw CancelledException('run was aborted by signal');
      },
    );
    agent.state.tools = [_tool('bash')];

    await agent.prompt('start the long thing');

    final toolResult = agent.state.messages
        .whereType<ToolResultMessage>()
        .single;
    final text = (toolResult.content.single as TextContent).text;
    expect(text, contains('Tool error (bash):'));
    expect(text, contains('run was aborted'));
    expect(text, contains('tool not started'));
    expect(text, isNot(contains('uncaught exception inside the harness')));
    // The cancel reason survives so the model (and the transcript) can see
    // WHO cancelled the run — e.g. the run-idle watchdog.
    expect(text, contains('run was aborted by signal'));
  });
}

The `factory / teammate` job is the review-leg agent (the review bot itself) that ran and "failed" as the review outcome — i.e., the AI review leg posted its review comments (the ones in pr_discussions) and exited with a failure outcome because it found issues. This is not a code/test CI failure — it's the review agent leg. The actual content of that failure is the review threads themselves (1 important + 2 suggestions). So the "CI failure" to fix is: address the review threads. There's no ci_failures_full.log locally; the failed check is the review leg. The rework flow says: CI failure = BLOCKING; the review leg found the issues that are the threads. So fixing the threads is the fix.

Actually wait — the review verdict was APPROVE. But the "factory/teammate" leg outcome was failure. The verdict comment says APPROVE with 1 important + 2 suggestions. The leg failing is the mechanism to arm rework. So the actionable work is the three threads.

Now, plan the fixes (TDD):

**Fix 1 (IMPORTANT)** — `_backgroundHandbackResult` supervisor-abort branch: route through `_truncateTail` and prepend `rewriteNotice`. The `_settledInlineResult` has the exact shaping code. To avoid duplication, I could extract a small helper `_shapeJobLogOutput(String rawOutput, {String? rewriteNotice})`. But careful about CRAP — the leg 3 rework split functions to keep CC low. Let me extract:

```dart
/// gh-1455 review: shape a settled/supervisor-abort job log exactly like
/// the classic inline path — tail-truncate, then head-prefix the rewrite
/// notice (the notice rides AFTER truncation: _truncateTail keeps the
/// TAIL, so a head-prefixed notice is cut exactly when the output is long
/// enough to truncate).
String _shapeJobLogOutput(String rawOutput, {String? rewriteNotice}) {
  final truncation = _truncateTail(rawOutput);
  var output = !truncation.truncated
      ? rawOutput
      : '${truncation.content}\n[Showing lines '
            '${truncation.totalLines - truncation.outputLines + 1}-'
            '${truncation.totalLines} of ${truncation.totalLines}.]';
  if (rewriteNotice != null) output = '$rewriteNotice\n$output';
  return output;
}
```

Then `_settledInlineResult` uses it, and `_backgroundHandbackResult` supervisor branch:

```dart
if (_isSupervisorAbort(cancelToken, yieldToken)) {
  final log = await env.readTextFile(entry.logPath);
  final rawOutput = log.isErr ? '' : log.valueOrNull!;
  // Review (gh-1455): the supervisor targets hung commands — the most
  // log-heavy case. Shape exactly like the settled path: tail-truncate
  // (a multi-MB log must never land in the transcript) and carry the
  // rewrite notice.
  var output = rawOutput;
  if (output.endsWith('\n')) {
    output = output.substring(0, output.length - 1);
  }
  throw StateError(
    _appendStatus(
      _shapeJobLogOutput(output, rewriteNotice: rewriteNotice),
      'Command aborted',
    ),
  );
}
