import 'dart:async';
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

void main() {
  test('debug', () async {
    final tempDir = Directory.systemTemp.createTempSync('dbg-');
    final env = LocalExecutionEnv(cwd: tempDir.path);
    final registry = ShellJobRegistry(env: env);
    final token = 'ghp_${'A' * 36}';
    final command = 'export GH_TOKEN=$token; '
        'i=0; while [ \$i -lt 4000 ]; do echo "line-\$i-padding"; '
        'i=\$((i+1)); done; sleep 60';
    print('command: $command');
    final runTokenSource = CancelTokenSource();
    final yieldSource = CancelTokenSource();
    final tool = shellTool(env, jobs: registry);
    final resultFuture = runZoned(
      () => tool.execute({'command': command}, runTokenSource.token, null),
      zoneValues: {yieldTokenZoneKey: yieldSource.token},
    );
    final deadline = DateTime.now().add(const Duration(seconds: 5));
    while (registry.jobs.isEmpty) {
      if (DateTime.now().isAfter(deadline)) fail('no job');
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }
    final entry = registry.jobs.single;
    print('logPath=${entry.logPath} isRunning=${entry.isRunning}');
    await Future<void>.delayed(const Duration(seconds: 2));
    print('after 2s: isRunning=${entry.isRunning}');
    final f = File(entry.logPath);
    print('absolute? ${entry.logPath.startsWith("/")} exists=${f.existsSync()}');
    if (f.existsSync()) {
      final s = f.readAsStringSync();
      print('log size=${s.length} head=${s.substring(0, s.length > 200 ? 200 : s.length)}');
    }
    runTokenSource.cancel(const StuckCallFollowUp('cancel_retry: stuck'));
    try {
      await resultFuture;
      print('NO ERROR THROWN');
    } on StateError catch (e) {
      print('THREW: len=${e.message.length}');
      print(e.message.substring(0, e.message.length > 300 ? 300 : e.message.length));
    }
    await entry.stop();
    await registry.jobs.first.settled;
    tempDir.deleteSync(recursive: true);
  });
}
EOF
